package com.bank.reflect;

import java.math.BigDecimal;
import java.math.RoundingMode;

// Fee logic EXTRACTED into its own class with a PUBLIC method,
// so tests verify it through the contract — no reflection needed.
class FeeCalculator {
    private static final BigDecimal RATE = new BigDecimal("0.0005"); // 0.05%

    public BigDecimal feeFor(BigDecimal amount) {
        return amount.multiply(RATE).setScale(2, RoundingMode.HALF_UP);
    }
}
