package com.bank.reflect;

import java.math.BigDecimal;

// Delegates fee computation to FeeCalculator instead of hiding it in a
// private method that tests would be tempted to reflect into.
class TransferService {
    private final FeeCalculator feeCalculator = new FeeCalculator();

    public BigDecimal totalDebit(BigDecimal amount) {
        return amount.add(feeCalculator.feeFor(amount));
    }
}
