package com.bank.reflect;

import java.lang.reflect.Field;
import java.util.StringJoiner;

// Generic auditor: logs EVERY field of ANY object using reflection.
// Legitimate because it must work on types unknown at compile time.
class ReflectiveAuditor {

    String audit(Object obj) throws IllegalAccessException {
        Class<?> clazz = obj.getClass();
        StringJoiner sj = new StringJoiner(", ", clazz.getSimpleName() + "{", "}");
        for (Field f : clazz.getDeclaredFields()) {
            f.setAccessible(true);            // reach private fields for auditing
            Object value = f.get(obj);        // read the field value dynamically
            sj.add(f.getName() + "=" + value);
        }
        return sj.toString();
    }
}
