package com.bank.reflect;

import java.lang.reflect.Method;
import java.math.BigDecimal;
import java.util.logging.*;

public class ReflectionDemo {
    private static final Logger log = Logger.getLogger(ReflectionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));

        // 1) Generic reflective audit — legitimate use (unknown type at compile time).
        ReflectiveAuditor auditor = new ReflectiveAuditor();
        log.info(() -> {
            try { return "Reflective audit: " + auditor.audit(rajesh); }
            catch (IllegalAccessException e) { return "audit failed"; }
        });

        // 2) Reflectively read a specific field via Class/Field.
        java.lang.reflect.Field balanceField = Account.class.getDeclaredField("balance");
        balanceField.setAccessible(true);
        Object bal = balanceField.get(rajesh);
        log.info(() -> "Reflectively read balance field: " + bal);

        // 3) Reflectively invoke a PUBLIC method via Method.invoke (how JUnit/Spring call).
        Method m = TransferService.class.getDeclaredMethod("totalDebit", BigDecimal.class);
        TransferService svc = new TransferService();
        Object total = m.invoke(svc, new BigDecimal("100000"));
        log.info(() -> "Reflectively invoked totalDebit(100000) = " + total);

        // 4) The GOOD design: fee logic lives in FeeCalculator, tested via PUBLIC method.
        BigDecimal fee = new FeeCalculator().feeFor(new BigDecimal("100000"));
        log.info(() -> "FeeCalculator.feeFor(100000) = " + fee + " (tested publicly, NOT reflected)");

        log.warning(() -> "Smell: reflecting into a private fee method in a test would couple the "
                + "test to internals; extracting FeeCalculator makes it publicly testable.");
    }
}

